#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, rank;
    DSU(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return;
        if (rank[px] < rank[py]) swap(px, py);
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    int N;
    cin >> S >> N;
    int len = S.size();
    DSU dsu(len);

    for (int i = 0; i < N; i++) {
        int l, r;
        cin >> l >> r;
        l--; r--;
        for (int j = l; j < r; j++) {
            dsu.unite(j, j + 1);
        }
    }

    for (int i = 0; i < len / 2; i++) {
        int j = len - 1 - i;
        if (dsu.find(i) != dsu.find(j)) {
            if (S[i] != S[j]) {
                cout << "No\n";
                return 0;
            }
        }
    }
    cout << "Yes\n";
    return 0;
}

