bool solvable(vector<vector<int>>& A, vector<int>& b, int mod) {
    int m = A.size(), n = A[0].size();
    vector<vector<int>> mat(m, vector<int>(n+1));
    for(int i=0;i<m;i++){for(int j=0;j<n;j++) mat[i][j]=((A[i][j]%mod)+mod)%mod; mat[i][n]=((b[i]%mod)+mod)%mod;}
    int row=0;
    for(int col=0;col<n&&row<m;col++){
        int pivot=-1;
        for(int i=row;i<m;i++) if(mat[i][col]!=0){pivot=i;break;}
        if(pivot==-1) continue;
        swap(mat[row],mat[pivot]);
        // find inverse of mat[row][col] mod p
        int inv=1; for(int x=1;x<mod;x++) if((mat[row][col]*x)%mod==1){inv=x;break;}
        for(int j=0;j<=n;j++) mat[row][j]=mat[row][j]*inv%mod;
        for(int i=0;i<m;i++) if(i!=row&&mat[i][col]!=0){int f=mat[i][col]; for(int j=0;j<=n;j++) mat[i][j]=(mat[i][j]-f*mat[row][j]%mod+mod*mod)%mod;}
        row++;
    }
    for(int i=row;i<m;i++) if(mat[i][n]!=0) return false;
    return true;
}

