        cin >> L >> R;
        --L; --R;
        diff[L] ^= 1;
        if (R + 1 < M) diff[R + 1] ^= 1;
    }

    // parity[x] = whether position x can be incremented independently
    // from position x-1 by combining operations.
    vector<int> parity(M, 0);
    int cur = 0;
    for (int i = 0; i < M; ++i) {
        cur ^= diff[i];
        parity[i] = cur;
    }

    // Build connected components where adjacent positions i-1 and i
    // are connected iff parity[i] == 0.
    // Inside one component, all positions always receive the same total increment mod 26.
    vector<int> comp(M, 0);
    int cid = 0;
    comp[0] = cid;
    for (int i = 1; i < M; ++i) {
        if (parity[i] == 0) comp[i] = cid;
        else comp[i] = ++cid;
    }

    int C = cid + 1;
    vector<vector<pair<int,int>>> g(C);

    auto add_edge = [&](int a, int b, int w) {
        g[a].push_back({b, w});
        g[b].push_back({a, (26 - w) % 26});
    };

    // For palindrome, positions i and j=M-1-i must become equal:
    // x[comp(j)] - x[comp(i)] = S[i] - S[j] (mod 26)
    for (int i = 0; i < M / 2; ++i) {
        int j = M - 1 - i;
        int a = comp[i], b = comp[j];
        int w = ((S[i] - 'a') - (S[j] - 'a')) % 26;
        if (w < 0) w += 26;

        if (a == b) {
            if (w != 0) {
                cout << "NO\n";
                return 0;
            }
        } else {
            add_edge(a, b, w);
        }
    }

    // Check consistency of difference constraints on each connected component.
    vector<int> val(C, -1);
    for (int s = 0; s < C; ++s) {
        if (val[s] != -1) continue;
        val[s] = 0;
        queue<int> q;
        q.push(s);

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (auto [v, w] : g[u]) {
                int need = (val[u] + w) % 26;
                if (val[v] == -1) {
                    val[v] = need;
                    q.push(v);
                } else if (val[v] != need) {
                    cout << "NO\n";
                    return 0;
                }
            }
        }
    }

    cout << "YES\n";
    return 0;
}

