#define MAXN 200005

int parent[MAXN], rank[MAXN], val[MAXN]; // val[x] = (shift[x] - shift[find(x)]) mod 26

int find(int x) {
    if (parent[x] != x) {
        int orig_parent = parent[x];
        parent[x] = find(parent[x]);
        val[x] = (val[x] + val[orig_parent]) % 26;
    }
    return parent[x];
}

int union_set(int a, int b, int diff) {
    // We want shift[a] - shift[b] = diff (mod 26)
    int ra = find(a), rb = find(b);
    if (ra == rb) {
        return ((val[a] - val[b] + 26) % 26 == diff);
    }
    // attach ra under rb
    if (rank[ra] < rank[rb]) {
        parent[ra] = rb;
        // val[a] - val[b] = diff
        // shift[a] = val[a] + shift[ra]
        // shift[b] = val[b] + shift[rb]
        // We need (val[a] + shift[ra]) - (val[b] + shift[rb]) = diff
        // shift[ra] - shift[rb] = diff - val[a] + val[b]
        val[ra] = (diff - val[a] + val[b] + 26) % 26;
    } else {
        parent[rb] = ra;
        // shift[b] - shift[ra] = ?
        // shift[a] - shift[b] = diff
        // val[a] + shift[ra] - (val[b] + shift[rb]) = diff
        // shift[rb] - shift[ra] = val[a] - val[b] - diff
        val[rb] = (val[a] - val[b] - diff + 26) % 26;
        if (rank[ra] == rank[rb]) rank[ra]++;
    }
    return 1;
}

int main() {
    char S[MAXN];
    int N, M;
    scanf("%s", S);
    N = strlen(S);
    scanf("%d", &M);
    for (int i = 0; i <= N; i++) {
        parent[i] = i;
        rank[i] = 0;
        val[i] = 0;
    }
    for (int i = 0; i < M; i++) {
        int L, R;
        scanf("%d %d", &L, &R);
        L--; // convert to 0-index
        // operation adds +1 to [L,R], which means diff[L]++, diff[R+1]--
        // In terms of shifts: shift[L] += 1, shift[R+1] -= 1
        // So we connect L and R+1 with diff = 1
        if (!union_set(L, R+1, 1)) {
            printf("No\n");
            return 0;
        }
    }
    // Now check palindrome condition
    for (int i = 0; i < N/2; i++) {
        int j = N - 1 - i;
        // We need shift[i] - shift[j] = (S[j] - S[i]) mod 26
        int diff_needed = (S[j] - S[i] + 26) % 26;
        if (!union_set(i, j, diff_needed)) {
            printf("No\n");
            return 0;
        }
    }
    printf("Yes\n");
    return 0;
