    for (int i = 0; i < N; i++) {
        int L, R;
        scanf("%d %d", &L, &R);
        diff[L - 1]++;   // use boundary positions 0..M-1 between chars
        diff[R]--;
    }

    int *w = (int *)malloc(M * sizeof(int));
    int cur = 0;
    for (int i = 0; i < M; i++) {
        cur += diff[i];
        w[i] = cur;
    }

    int *g = (int *)malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) g[i] = 0;

    for (int i = 0; i + 1 < M; i++) {
        g[i + 1] = gcd_int(g[i], w[i]);
    }

    int *rg = (int *)malloc((M + 1) * sizeof(int));
    rg[M] = 0;
    for (int i = M - 1; i >= 0; i--) {
        rg[i] = gcd_int(rg[i + 1], w[i]);
    }

    int pairs = M / 2;
    int V = M;
    int Emax = pairs * 2 + M;
    Edge *edges = (Edge *)malloc(Emax * sizeof(Edge));
    int *head = (int *)malloc(V * sizeof(int));
    for (int i = 0; i < V; i++) head[i] = -1;
    int ecnt = 0;

    for (int i = 0; i < pairs; i++) {
        int j = M - 1 - i;
        int d = ((S[j] - S[i]) % 26 + 26) % 26;

        int gg = 0;
        if (i + 1 <= j) {
            gg = gcd_int(g[i + 1], rg[j + 1]);
        } else {
            gg = 0;
        }

        if (d == 0) continue;

        if (gg == 0 || (d % gcd_int(gg, 26)) != 0) {
            printf("NO\n");
            free(S); free(diff); free(w); free(g); free(rg); free(edges); free(head);
            return 0;
