        edges[ecnt].to = j;
        edges[ecnt].next = head[i];
        head[i] = ecnt++;

        edges[ecnt].to = i;
        edges[ecnt].next = head[j];
        head[j] = ecnt++;
    }

    int *queue = (int *)malloc(V * sizeof(int));
    int *vis = (int *)calloc(V, sizeof(int));
    int *color = (int *)malloc(V * sizeof(int));

    for (int s = 0; s < V; s++) {
