            int v = queue[front++];
            for (int e = head[v]; e != -1; e = edges[e].next) {
                int to = edges[e].to;
                if (!vis[to]) {
                    vis[to] = 1;
                    color[to] = color[v] ^ 1;
                    cnt[color[to]]++;
                    queue[back++] = to;
