import java.util.*;

public class Main {
    static int mod;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int n = S.length();
        int N = sc.nextInt();
        int[] L = new int[N], R = new int[N];
        for (int i = 0; i < N; i++) {
            L[i] = sc.nextInt() - 1;
            R[i] = sc.nextInt() - 1;
        }

        for (int m : new int[]{2, 13}) {
            mod = m;
            if (!feasible(S, n, N, L, R, m)) {
                System.out.println("No");
                return;
            }
        }
        System.out.println("Yes");
    }

    static boolean feasible(String S, int n, int N, int[] L, int[] R, int m) {
        // Build augmented matrix
        int rows = n / 2;
        int cols = N;
        int[][] mat = new int[rows][cols + 1];
        for (int j = 0; j < rows; j++) {
            int mirror = n - 1 - j;
            for (int i = 0; i < N; i++) {
                int inJ = (L[i] <= j && j <= R[i]) ? 1 : 0;
                int inM = (L[i] <= mirror && mirror <= R[i]) ? 1 : 0;
                mat[j][i] = ((inJ - inM) % m + m) % m;
            }
            mat[j][cols] = ((S.charAt(mirror) - S.charAt(j)) % m + m) % m;
        }
        return gaussianCheck(mat, rows, cols, m);
    }
    // Gaussian elimination, return false if inconsistent
    static boolean gaussianCheck(int[][] mat, int rows, int cols, int m) {
        int r = 0;
        for (int c = 0; c < cols && r < rows; c++) {
            int pivot = -1;
            for (int i = r; i < rows; i++) if (mat[i][c] != 0) { pivot = i; break; }
            if (pivot == -1) continue;
            int[] tmp = mat[r]; mat[r] = mat[pivot]; mat[pivot] = tmp;
            int inv = modInverse(mat[r][c], m);
            for (int j = c; j <= cols; j++) mat[r][j] = mat[r][j] * inv % m;
            for (int i = 0; i < rows; i++) {
                if (i != r && mat[i][c] != 0) {
                    int f = mat[i][c];
                    for (int j = c; j <= cols; j++) mat[i][j] = ((mat[i][j] - f * mat[r][j]) % m + m) % m;
                }
            }
            r++;
        }
        for (int i = r; i < rows; i++) if (mat[i][cols] != 0) return false;
        return true;
    }
    static int modInverse(int a, int m) {
        for (int i = 1; i < m; i++) if (a * i % m == 1) return i;
        return -1;
    }
}

