public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();   // length of S
        int m = fs.nextInt();   // number of operation types
        String s = fs.next();

        // diff[i] over edges 1..n-1:
        // applying [L, R] toggles all edges L..R-1
        int[] diff = new int[n + 2];
        for (int i = 0; i < m; i++) {
            int l = fs.nextInt();
            int r = fs.nextInt();
            if (l < r) {
                diff[l] ^= 1;
                diff[r] ^= 1;
            }
        }

        // Build graph of positions connected by available edge toggles.
        // If edge i is available, positions i and i+1 are in same component.
        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int cur = 0;
        for (int i = 1; i <= n - 1; i++) {
            cur ^= diff[i];
            if (cur == 1) union(i - 1, i, parent, size);
        }

        // For each mirrored pair, required difference must be achievable:
        // positions in same component can differ by any value mod 26;
        // positions in different components must stay with original difference.
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (find(i, parent) != find(j, parent)) {
                if (s.charAt(i) != s.charAt(j)) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
    }

    static int find(int x, int[] parent) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static void union(int a, int b, int[] parent, int[] size) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int t = ra; ra = rb; rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}
